(()=>{const id='calendar-compact-overrides';if(document.getElementById(id))return;const s=document.createElement('style');s.id=id;s.textContent=`
/* Calendário compacto: mais datas visíveis e navegação mais rápida. */
.calendar-months>.sticky{padding:.35rem .5rem!important;gap:.4rem!important;border-radius:.65rem!important}
.calendar-view-switch{gap:.15rem!important;padding:.15rem!important;border-radius:.6rem!important}
.calendar-view-btn{min-height:26px!important;padding:.22rem .42rem!important;border-radius:.46rem!important;font-size:8.5px!important;gap:.2rem!important}

.calendar-months.calendar-mobile-list{gap:.7rem!important}
.calendar-months.calendar-mobile-list .calendar-month-card{padding:.62rem!important}
.calendar-months.calendar-mobile-list .calendar-month-grid{gap:.28rem!important}
.calendar-months.calendar-mobile-list .calendar-day-card{min-height:0!important;height:auto!important;padding:.4rem .5rem!important;gap:.25rem!important;border-radius:.62rem!important}
.calendar-months.calendar-mobile-list .calendar-day-number{font-size:11px!important}
.calendar-months.calendar-mobile-list .calendar-day-name-mobile{font-size:8px!important}
.calendar-months.calendar-mobile-list .calendar-shift{grid-template-columns:3.8rem minmax(0,1fr)!important;gap:.35rem!important;padding:.28rem .4rem!important;border-radius:.42rem!important;font-size:9.5px!important;line-height:1.18!important}
.calendar-months.calendar-mobile-list .calendar-shift-period{font-size:8.5px!important;padding-top:0!important}
.calendar-months.calendar-mobile-list .calendar-shift-text{font-size:9.5px!important;line-height:1.18!important}

.calendar-months.calendar-mobile-grid .calendar-month-card{padding:.55rem!important}
.calendar-months.calendar-mobile-grid .calendar-month-grid{gap:.35rem!important}
.calendar-months.calendar-mobile-grid .calendar-day-card{min-height:104px!important;padding:.4rem!important}
.calendar-months.calendar-mobile-grid .calendar-empty{min-height:104px!important}

@media(max-width:767px){
.calendar-months>.sticky>div:first-child span:last-child{display:none!important}
.calendar-months.calendar-mobile-grid .calendar-empty{min-height:70px!important}
.calendar-months.calendar-mobile-grid .calendar-day-card{min-height:70px!important;height:70px!important;padding:.18rem!important;gap:.12rem!important}
.calendar-months.calendar-mobile-grid .calendar-day-number{font-size:9px!important}
.calendar-months.calendar-mobile-grid .calendar-shift{padding:.1rem .14rem!important;font-size:6px!important;gap:.08rem!important}
.calendar-months.calendar-mobile-grid .calendar-shift-period,.calendar-months.calendar-mobile-grid .calendar-shift-text{font-size:6px!important}
}
`;document.head.appendChild(s)})();
